mapper.select:
SELECT *
FROM lunaerp_business_quotation
WHERE id = #{id}
  AND deleted = 1
  AND status = 'DRAFT'
  AND tenant_id = #{tenantId}

mapper.update:
UPDATE lunaerp_business_quotation
SET deleted = 0,
    status = 'DRAFT',
    updater = #{updater},
    update_time = #{now}
WHERE id = #{id}
  AND deleted = 1
  AND status = 'DRAFT'
  AND tenant_id = #{tenantId}

mapper.delete:
DELETE FROM lunaerp_business_quotation
WHERE id = #{id}
  AND deleted = 1
  AND status = 'DRAFT'
  AND tenant_id = #{tenantId}

mapper.select:
SELECT COUNT(1)
FROM lunaerp_business_sales_contract
WHERE source_quotation_id = #{quotationId}
  AND deleted = 0
  AND tenant_id = #{tenantId}
